import { invoke } from '@tauri-apps/api/core';

function getPassword(service, user) {
    return invoke("plugin:keyring|get_password", {
        service,
        user,
    });
}
function setPassword(service, user, password) {
    return invoke("plugin:keyring|set_password", {
        service,
        user,
        password,
    });
}
function deletePassword(service, user) {
    return invoke("plugin:keyring|delete_password", {
        service,
        user,
    });
}
function getSecret(service, user) {
    return invoke("plugin:keyring|get_secret", {
        service,
        user,
    }).then((result) => (result ? new Uint8Array(result) : null));
}
function setSecret(service, user, secret) {
    return invoke("plugin:keyring|set_secret", {
        service,
        user,
        secret,
    });
}
function deleteSecret(service, user) {
    return invoke("plugin:keyring|delete_secret", {
        service,
        user,
    });
}

export { deletePassword, deleteSecret, getPassword, getSecret, setPassword, setSecret };
